import{_ as r,a0 as i,w as h,s as l,ao as s,I as p,x as e,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse(`{"title":"Cheat—— 给Linux初学者和管理员一个终极命令行‘备忘单’ | LCTT x X-CMD","titleTemplate":false,"description":"Cheat—— 给Linux初学者和管理员一个终极命令行‘备忘单’ | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cheat—— 给Linux初学者和管理员一个终极命令行‘备忘单’ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cheat—— 给Linux初学者和管理员一个终极命令行‘备忘单’ | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140804 Cheat--An Ultimate Command Line 'Cheat-Sheet' for Linux Beginners and Administrators","title":"Cheat—— 给Linux初学者和管理员一个终极命令行‘备忘单’","tag":"201409","desc":""},"relativePath":"201409/20140804 Cheat--An Ultimate Command Line 'Cheat-Sheet' for Linux Beginners and Administrators.md","filePath":"[post].md"}`),c={name:"201409/20140804 Cheat--An Ultimate Command Line 'Cheat-Sheet' for Linux Beginners and Administrators.md"};function m(d,t,g,u,w,C){const n=i("Link");return h(),l("div",null,[t[16]||(t[16]=s(`<h1 id="cheat——-给linux初学者和管理员一个终极命令行-备忘单" tabindex="-1">Cheat—— 给Linux初学者和管理员一个终极命令行‘备忘单’ <a class="header-anchor" href="#cheat——-给linux初学者和管理员一个终极命令行-备忘单" aria-label="Permalink to “Cheat—— 给Linux初学者和管理员一个终极命令行‘备忘单’”">​</a></h1><p>当你不确定你所运行的命令，尤其是那些使用了许多选项的复杂命令时，你会怎么做？在这种情况下，我们使用man pages来获取帮助。还有一些其它的选择可能包括像‘<strong>help</strong>’，‘<strong>whereis</strong>’和‘<strong>whatis</strong>’这样的命令。但是所有的这些既有优点，也有缺点。</p><p>当我们浏览<strong>man pages</strong>来查看选项和帮助的时候，里面的描述实在太冗长了，我们无法在短的时间里理解它的意思。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Linux-Man-Pages.jpeg" alt="Linux Man Pages"> Linux Man Pages</p><p>同样，‘<strong>help</strong>’命令可能也不会给你期待的答案。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/help-command.jpeg" alt="Help Command"> Help Command</p><p>‘<strong>whereis</strong>’命令几乎不给你任何信息，除了安装二进制文件的位置（有些时候可能是重要的）</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/whereis-command.jpeg" alt="Whereis Command"> Whereis Command</p><p>‘<strong>whatis</strong>’命令给出一套很严格的答案，它除了说出所查询命令的作用，并没有什么太大帮助。而且，它从来不说明可用的选项。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/whatis-command.jpeg" alt="Whatis Command"> Whatis Command</p><p>直到在困难中解决问题前，我们已经使用了以上全部选项，但是现在来了一个交互式的备忘录应用程序‘<strong>cheat</strong>’，它将在其余的命令中脱颖而出。</p><h3 id="什么是cheat" tabindex="-1">什么是cheat? <a class="header-anchor" href="#什么是cheat" aria-label="Permalink to “什么是cheat?”">​</a></h3><p><strong>cheat</strong>是在GNU通用公共许可证下，为Linux命令行用户发行的交互式备忘单应用程序。它提供显示Linux命令使用案例，包括该命令所有的选项和简短但尚可理解的功能。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/cheat-sheet.jpeg" alt="Cheat: Provides Easy Command Options"></p><p>Cheat：提供简单命令选项</p><h3 id="在linux系统中安装-cheat" tabindex="-1">在Linux系统中安装‘Cheat’ <a class="header-anchor" href="#在linux系统中安装-cheat" aria-label="Permalink to “在Linux系统中安装‘Cheat’”">​</a></h3><p>‘<strong>Cheat</strong>’有两个主要的依赖——‘<strong>python</strong>’ 和 ‘<strong>pip</strong>’，在安装‘<strong>cheat</strong>’之前，确保你的系统安装了python和pip。</p><h3 id="install-python" tabindex="-1">Install Python <a class="header-anchor" href="#install-python" aria-label="Permalink to “Install Python”">​</a></h3><pre><code># apt-get install Python (基于Debian的系统)
# yum install python (基于小红帽的系统)
</code></pre><p>Install Pip</p><pre><code># apt-get install python-pip (基于Debian的系统)
# yum install python-pip (基于小红帽的系统)
</code></pre><p><strong>Note</strong>：pip是一个简单的安装替代，是一个有极大改进的Python第三方包安装器。</p><h3 id="下载并安装cheat" tabindex="-1">下载并安装Cheat <a class="header-anchor" href="#下载并安装cheat" aria-label="Permalink to “下载并安装Cheat”">​</a></h3><p>我们将通过Git下载‘Cheat’，确保你安装了‘git’包，如果没有最好安装一下。</p><pre><code># apt-get install git (基于Debian的系统)
# yum install git (基于小红帽的系统)
</code></pre><p>接下来，通过运行下面的命令来安装所需要的python依赖包。</p><pre><code># pip install docopt pygments
</code></pre>`,27)),p("p",null,[t[1]||(t[1]=e("现在，复制cheat的",-1)),a(n,{href:"http://www.tecmint.com/install-git-to-create-and-share-your-own-projects-on-github-repository/"},{default:o(()=>[...t[0]||(t[0]=[e("Git库",-1)])]),_:1})]),t[17]||(t[17]=s(`<pre><code># git clone https://github.com/chrisallenlane/cheat.git
</code></pre><p>进入cheat目录，运行‘<strong>setup.py</strong>’（一个python脚本）。</p><pre><code># cd cheat
# python setup.py install
</code></pre><p>如果安装很顺利，你就能够看到安装在系统上的cheat版本了。</p><pre><code># cheat -v
cheat 2.0.9
</code></pre><h3 id="cheat的一些必要配置" tabindex="-1">cheat的一些必要配置 <a class="header-anchor" href="#cheat的一些必要配置" aria-label="Permalink to “cheat的一些必要配置”">​</a></h3><p>你必须在‘~/.bashrc’文件里设置‘<strong>EDITOR</strong>’环境变量，打开用户‘<strong>.bashrc</strong>’文件，然后把下面这行加入到里面：</p><pre><code>export EDITOR = /usr/bin/nano
</code></pre><p>你可以使用你喜欢的编辑器来替代‘<strong>nano</strong>’。保存文件然后退出，再次登录以确保修改生效。</p><p>接下来，添加cheat的自动补全特性，来确保不同解释器下命令行的自动补全。为了到达该功能要求，简单地将‘<strong>cheat.bash</strong>’脚本clone下来，然后复制到你系统正确的路径下。</p><pre><code># wget https://github.com/chrisallenlane/cheat/raw/master/cheat/autocompletion/cheat.bash 
# mv cheat.bash /etc/bash_completion.d/
</code></pre><p><strong>NOTE</strong>：团队已经在Git上上传了其他解释器的自动补全脚本，这些都可以被克隆，然后用在不同的解释器上。使用下面的链接，以找到其余解释器的自动补全脚本：</p>`,12)),p("ul",null,[p("li",null,[a(n,{href:"https://github.com/chrisallenlane/cheat/tree/master/cheat/autocompletion"},{default:o(()=>[...t[2]||(t[2]=[e("Auto Completion Script for Various Shells",-1)])]),_:1})])]),t[18]||(t[18]=s(`<p>不仅如此，如果需要的话，你也可以使用语法高亮。要想做到这一点，在你的‘<strong>.bashrc</strong>’文件中添加‘<strong>CHEATCOLORS</strong>’环境变量。</p><pre><code>export CHEATCOLOR=true
</code></pre><p>Cheat应用默认只提供最基本和最常用的命令。cheat备忘单的内容保存在<strong>~/.cheat/.</strong>目录里，我们可以手动在这个目录添加备忘单里面的内容，这样，我们的cheat应用将更强大。</p><pre><code># cheat -xyz
</code></pre><p>这将打开xyz备忘单，如果没有的话就会创建一个。备忘单将使用<strong>.bashrc</strong>里设置的默认<strong>编辑器</strong>打开，默认编辑器就是在上面<strong>.bashrc</strong>所设置的。</p><h3 id="一些cheat命令的使用" tabindex="-1">一些Cheat命令的使用 <a class="header-anchor" href="#一些cheat命令的使用" aria-label="Permalink to “一些Cheat命令的使用”">​</a></h3><p>一个包可以是 *.gz , *.bz2 , *.zip , *.xz，可是什么情况下用哪些选项呢？</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/cheat-tar.jpeg" alt="tar command options"> tar命令选项</p><p>除非在不同的地方咨询和核对后，我才使用<strong>dd</strong>命令，在此之前，无论我对这个命令多么的肯定，我从不使用它。现在，事情就变得简单多了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/cheat-dd.jpeg" alt="dd command options"> dd命令选项</p><p>‘<strong>uname</strong>’命令帮助</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/uname-command.jpeg" alt="uname command options"> uname命令选择</p><p>一个简短的<strong>ifconfig</strong>命令操作教程</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/ifconfig-command.jpeg" alt="ifconfig command options"> ifconfig命令选项</p><p>‘top’命令，对管理员和普通用户来说，是最重要的命令之一。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/top-command.jpeg" alt="top command options"> top命令选项</p><p>我们来骗骗cheat命令，如何（尽管别有意义）？得到一个可用命令的列表，其实就是安装在你系统里的cheat备忘录。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/linux-commands.jpeg" alt="List All Linux Commands"> 列出所有Linux命令</p><p>使用关键字搜索备忘单。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/search-cheat-sheet.jpeg" alt="Search Cheat Sheet"> 搜索备忘单</p><p>来看看包含所有命令的内置备忘单。</p><pre><code>$ cheat -d

/home/avi/.cheat
/usr/local/lib/python2.7/dist-packages/cheat/cheatsheets
</code></pre><p>复制内置的备忘单到你的本地目录。</p><pre><code># cp /usr/local/lib/python2.7/dist-packages/cheat/cheatsheets/* /home/avi/.cheat/
</code></pre><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>这个超棒的工具在许多情况下担任“救世主”的角色，它给予你需要的信息，信息不冗余，不模糊，相反地，却击中要点。这是每个人都会需要的工具，很简单就能创建、安装，使用和理解，这个工具前途无量。</p><p>这个Git仓库已经添加了一个精彩的<strong>gag</strong>，这里我不打算去解释它，而留给各位来解释。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/linux-gag.jpeg" alt="Linux Gag"> Linux Gag</p><p>好了，文章就要结束了，我会带着下一篇你们喜欢的有趣文章回到这里的，在此之前，要时刻关注我们。别忘了在下面的评论部分给我们留下您宝贵的反馈信息。</p><hr>`,30)),p("p",null,[t[4]||(t[4]=e("via: ",-1)),a(n,{href:"http://www.tecmint.com/cheat-command-line-cheat-sheet-for-linux-users/"},{default:o(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/cheat-command-line-cheat-sheet-for-linux-users/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("作者：",-1)),a(n,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...t[5]||(t[5]=[e("Avishek Kumar",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),a(n,{href:"https://github.com/su-kaiyao"},{default:o(()=>[...t[6]||(t[6]=[e("su-kaiyao",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),a(n,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[7]||(t[7]=[e("Caroline",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),a(n,{href:"http://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const b=r(c,[["render",m]]);export{T as __pageData,b as default};
